// Aggregate all sheet rows into a single item with an array of seen IDs.
// This runs ONCE per workflow execution, not once per comment.
const rows = $input.all();
const seenIds = rows.map(r => r.json.commentId).filter(Boolean);
return [{ json: { seenIds } }];

const videoIds = [
  'VIDEO_ID_1',
  'VIDEO_ID_2',
  'VIDEO_ID_3'
];
return videoIds.map(id => ({ json: { videoId: id } }));

// Read the seen IDs built once at the start of the run.
// Use .first() here is correct because Build Seen IDs Set always outputs exactly 1 item.
const seenIds = new Set($('Build Seen IDs Set').first().json.seenIds || []);
const results = [];

for (const item of $input.all()) {
  const comments = item.json.items || [];
  for (const comment of comments) {
    const snippet = comment.snippet.topLevelComment.snippet;
    const commentId = comment.snippet.topLevelComment.id;
    if (!seenIds.has(commentId)) {
      results.push({
        json: {
          commentId,
          videoId: comment.snippet.videoId,
          authorName: snippet.authorDisplayName,
          text: snippet.textDisplay,
          publishedAt: snippet.publishedAt,
          likeCount: snippet.likeCount
        }
      });
    }
  }
}

// Returning [] stops execution cleanly when there are no new comments.
return results;

const item = $input.first();
const aiRaw = item.json.message.content;

let parsed;
try {
  parsed = JSON.parse(aiRaw);
} catch(e) {
  parsed = {
    category: 'OTHER',
    confidence: 0,
    reason: 'Parse error',
    draft_reply: 'Thank you for your comment!'
  };
}

const skipCategories = ['SPAM', 'HATE_SPEECH'];

return [{
  json: {
    ...item.json,
    category: parsed.category,
    confidence: parsed.confidence,
    reason: parsed.reason,
    draft_reply: parsed.draft_reply,
    skip: skipCategories.includes(parsed.category)
  }
}];

